                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1
                                and labels[yy][xx] < 0):
                            labels[yy][xx] = k
                            cells.append((yy, xx))
                comps.append(cells)

    # Find enclosed zero regions and the outline components enclosing them.
    seen = [[False] * w for _ in range(h)]
    cavities = []
    closed = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            cells = [(r, c)]
            seen[r][c] = True
            edge = False
            borders = set()
            for y, x in cells:
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if grid[yy][xx] == 1:
                            borders.add(labels[yy][xx])
                        elif not seen[yy][xx]:
                            seen[yy][xx] = True
                            cells.append((yy, xx))
            if not edge:
                cavities.append(cells)
                closed.update(borders)

    inner = set(p for region in cavities for p in region)

    # Color the 8-neighbor inner rim of each cavity 3.
    for region in cavities:
        for y, x in region:
            if any(0 <= y + dy < h and 0 <= x + dx < w and grid[y + dy][x + dx] == 1
                   for dy in (-1, 0, 1) for dx in (-1, 0, 1)
                   if (dy, dx) != (0, 0)):
                out[y][x] = 3

    # Add the 8-neighbor exterior halo around each closed outline in color 2.
    for k in closed:
        for y, x in comps[k]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0
                            and (yy, xx) not in inner):
                        out[yy][xx] = 2
    return out
